mapper.update:
UPDATE reviews
SET improvement = #{improvement},
    updated_at = #{now}
WHERE id = #{reviewId}
  AND user_id = #{userId}
  AND deleted_at IS NULL
  AND next_plan_id IS NULL

UPDATE reviews
SET next_plan_id = #{nextPlanId},
    transferred_at = #{now},
    updated_at = #{now}
WHERE id = #{reviewId}
  AND user_id = #{userId}
  AND deleted_at IS NULL
  AND next_plan_id IS NULL
  AND EXISTS (
      SELECT 1
      FROM plans np
      WHERE np.id = #{nextPlanId}
        AND np.user_id = #{userId}
        AND np.deleted_at IS NULL
  )
